def find_rectangles(changed_mask, rows, cols):
    """Find all rectangular blocks of True values"""
    rectangles = []
    visited = set()

    # Find all connected components (using flood fill)
    for r in range(rows):
        for c in range(cols):
            if changed_mask[r, c] and (r, c) not in visited:
                # Flood fill to find component
                component = [(r, c)]
                queue = [(r, c)]
                while queue:
                    curr_r, curr_c = queue.pop(0)
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if changed_mask[nr, nc] and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                component.append((nr, nc))
                                queue.append((nr, nc))

                # Check if component is a rectangle
                min_r, max_r = min(r for r, c in component), max(r for r, c in component)
                min_c, max_c = min(c for r, c in component), max(c for r, c in component)

                expected_size = (max_r - min_r + 1) * (max_c - min_c + 1)
                if len(component) == expected_size:
